  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","locale":"de","product_id":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","seo":{"pageTitle":"Gapyeong-Tagestour ab Seoul — Insel Nami, Garden of Morning Calm & Petite France | AtoC Korea","metaDescription":"Bus-Gruppentagestour ab Seoul nach Gapyeong: die Metasequoien-Allee der Insel Nami, der Garden of Morning Calm und Petite France. Alle drei Eintritte inklusive. Abholung am Bahnhof Hongik University oder an der Station Myeongdong, zurück in Seoul bis 19:00.","title":"Gapyeong-Tagestour ab Seoul — Insel Nami, Morning Calm & Petite France","description":"Drei Wahrzeichen Gapyeongs an einem 11,5-stündigen Bustag ab Seoul, inklusive Fähre zur Insel Nami sowie Eintritt in den Garden of Morning Calm und nach Petite France.","primaryKeywords":["Gapyeong Tagestour ab Seoul","Nami Island Tour","Garden of Morning Calm Tour","Petite France Gapyeong","Tagesausflug ab Seoul Nami Island Morning Calm"],"ogImage":"https://www.atockorea.com/images/tours/nami-island/nami-metasequoia-sunset-lake.webp"},"catalog_card":{"slug":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","title":"Gapyeong-Tagestour ab Seoul: Insel Nami, Garden of Morning Calm & Petite France","subtitle":"Das Gapyeong-Trio an einem Bustag — keine Bergwanderung, drei Eintritte inklusive","region":"Seoul → Gyeonggi-do (Gapyeong)","duration":"11,5 Stunden","stopsCount":3,"rating":0,"reviewCount":0,"badges":["Tagesausflug ab Seoul","Gapyeong","Gruppentour zum Zusteigen","K-Drama","Gärten"],"tags":["Tagesausflug ab Seoul","Gapyeong","Gruppentour zum Zusteigen","K-Drama","Gärten","Familienfreundlich"],"heroImage":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","thumbnail":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","priceLabel":"","shortCardDescription":"Seouls unkompliziertester Landtag: die Metasequoien-Allee der Insel Nami, ein 330,000 m² großes Themen-Arboretum und ein Dorf zum Kleinen Prinzen — alle drei Eintritte inklusive, zurück in Seoul bis 19:00."},"headlineLine1":"Tagestour ab Seoul","headlineLine2":"Nami, Morning Calm & Petite France","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59},"hero":{"imageUrl":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","imagePosition":"center 45%","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp"],"tagline":"Gapyeongs drei bekannteste Stopps an einem entspannten Bustag ab Seoul — eine baumbestandene Flussinsel, Koreas bekanntester Privatgarten und ein offiziell lizenziertes Dorf zu „Le Petit Prince“","pills":["Tagesausflug ab Seoul","Gärten + Hallyu","Alle Eintritte inklusive"],"meta":{"duration":"11,5 Stunden","region":"Seoul → Gyeonggi-do (Gapyeong)","stops":"3 Stopps","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"Überblick"},{"id":"itinerary","label":"Ablauf"},{"id":"details","label":"Details"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"Bewertungen"}],"glanceItems":[{"icon":"clock","label":"Dauer","value":"11,5 Stunden"},{"icon":"camera","label":"Fotopotenzial","value":"Sehr hoch","level":5},{"icon":"mountain","label":"Landschaft","value":"Hoch","level":4},{"icon":"footprints","label":"Gehanteil","value":"Leicht bis mittel","level":2},{"icon":"cloud-rain","label":"Regentauglichkeit","value":"Mittel","level":3},{"icon":"users","label":"Familientauglichkeit","value":"Sehr gut","level":5},{"icon":"gauge","label":"Tempo","value":"Entspannt","level":3}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 1","alt":"Insel Nami (Namiseom) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 2","alt":"Insel Nami (Namiseom) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 3","alt":"Insel Nami (Namiseom) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 4","alt":"Insel Nami (Namiseom) — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 1","alt":"The Garden of Morning Calm — gallery image 1"},{"id":6,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 2","alt":"The Garden of Morning Calm — gallery image 2"},{"id":7,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 3","alt":"The Garden of Morning Calm — gallery image 3"},{"id":8,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 4","alt":"The Garden of Morning Calm — gallery image 4"},{"id":9,"type":"photo","src":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","location":"Petite France","caption":"Petite France — photo 1","alt":"Petite France — gallery image 1"},{"id":10,"type":"photo","src":"/images/tours/petite-france/petite-france-couple-colorful.webp","location":"Petite France","caption":"Petite France — photo 2","alt":"Petite France — gallery image 2"},{"id":11,"type":"photo","src":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","location":"Petite France","caption":"Petite France — photo 3","alt":"Petite France — gallery image 3"}],"itineraryStops":[{"number":1,"time":"07:30 / 08:00","duration":"30-Minuten-Fenster","name":"Abholung (Bahnhof Hongik University oder Station Myeongdong)","category":"Bus-Abholung","description":"Die Abholung erfolgt an einem von zwei Treffpunkten in Seoul: **(1) Starbucks am Bahnhof Hongik University, Ausgang 8 (Mapo-gu)** um 07:30 — die Starbucks-Filiale liegt unmittelbar oben an Ausgang 8; ODER **(2) Station Myeongdong, Ausgang 2 (Jung-gu)** um 08:00 — der NorthFace-Flagshipstore ist das sichtbare Wahrzeichen neben dem Ausgang.\n\nBeide Abholpunkte teilen sich denselben klimatisierten Bus, und die Gäste von Hongik steigen zuerst ein. Bitte seien Sie **5 Minuten vor der angegebenen Zeit** an Ihrem gewählten Punkt. Das ist ein merklich sanfterer Start als bei den Seoraksan-Tagestouren, die um 06:00 losfahren — Gapyeong liegt nah genug an Seoul, dass der Bus erst starten kann, wenn die ersten U-Bahnen bereits zwei Stunden fahren.\n\nDer Guide verteilt beim Einsteigen eine gedruckte koreanisch-englische Programmkarte und bestätigt den Ablauf des Tages, den Rastplatzstopp und die erwarteten Rückkehrzeiten. Von Myeongdong fährt der Bus auf der Schnellstraße Seoul-Chuncheon nach Nordosten, rund 1,5 Stunden bis zum Fähranleger Gapyeong.","image":null,"highlights":[],"timeUsed":["Treffen Sie 5 Minuten vor der angegebenen Zeit an Ihrem gewählten Abholpunkt ein (~5 Min.)","Bus von AtoC Korea am gekennzeichneten Starbucks / NorthFace erkennen (~5 Min.)","Einsteigen in der Abholschlange (~10 Min.)","Gedruckte koreanisch-englische Programmkarte wird beim Einsteigen verteilt"],"whyOnRoute":"Zwei Abholpunkte decken Seouls beide großen Besucherzentren ab: das Viertel um die Hongik University in Mapo-gu, das jüngeren und kurz bleibenden Reisenden entgegenkommt, und Myeongdong in Jung-gu, das klassische Touristenviertel um die Hotels Lotte, Shilla und Westin. Hongik zuerst und Myeongdong danach ist die natürliche Reihenfolge für eine Fahrt nach Nordosten auf die Schnellstraße Seoul-Chuncheon. Der Start um 07:30 ist spät genug, um bequem zu sein, und früh genug, um den Bus gegen 10:00 an die Nami-Fähre zu bringen — vor den Individualreisenden, die mit dem ITX-Zug anreisen.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Insel Nami (Namiseom)","time":"≈ 10:00","number":2,"category":"Flussinsel mit Fährzugang & K-Drama-Wahrzeichen","duration":"120 Min. (2 Stunden)","timeUsed":["Fährüberfahrt vom Fähranleger Gapyeong (5-10 Minuten inklusive Warteschlange)","Freie Gehzeit entlang der Metasequoien- / Ginkgo- / Korean-Pine-Alleen — Runde über die halbe Insel ~3 km","Optionale Fahrradmiete (Einzelrad 7,000 / Tandem 14,000 KRW pro Stunde) oder elektrischer blauer Zug (3,000 KRW einfach bis zur UNICEF Hall)","Kurze Snackpause auf der Insel (Sonata Cafe, Hotteok, Süßkartoffel-Latte)","Rückfähre zum Festland"],"_poi_meta":{"poi_key":"nami_island","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Nami Island official listing + visa fee schedule)","Naminara Republic Official Site (namisum-en.imweb.me — own corpus on cultural-independence brand)","UNICEF Korea (Nami Island 2010 Child Friendly Park designation + International Children''s Book Festival)","KBS / Korea Times (Winter Sonata 2002 production retrospectives + Japanese tourism boom coverage)","Wikipedia (Namiseom — open corpus on General Nami history + Cheongpyeong Dam 1944 origin)"]},"highlights":["Halbmondförmige Flussinsel, ~460,000 m² / 5 km Umfang; benannt nach General Nami (1441-1468)","Ikonische Metasequoien-Allee — der markante Drehort von Winter Sonata (2002)","Selbsterklärte „Naminara Republic“ seit 2006 — eigene Flagge, Währung, Pass (touristisches Konzept)","5-Minuten-Fähre vom Fähranleger Gapyeong (08:00-21:00, in Stoßzeiten alle 10-20 Min.)","Tierwelt auf der Insel: Pfauen (auch seltene Albinos), Strauße, wilde Kaninchen, Eichhörnchen","**Land entstanden 1944**, als der von Japan gebaute Cheongpyeong-Damm den Bukhan-Fluss anstaute","**Auszeichnung als UNICEF Child Friendly Park 2010** + Nami Island Arts & Education veranstaltet **jährlich über 600 Aufführungen/Ausstellungen/Festivals**"],"smartNotes":{"photo":"Die Metasequoien-Allee ist die weltberühmte Winter-Sonata-Aufnahme — am besten im Herbst (goldgelb, Ende Oktober bis Anfang November) oder im Winter (Schnee). Die Riverside Lover''s Ginkgo Tree Lane im Süden ist ruhiger und ebenso fotogen. Der Albino-Pfau zeigt sich gelegentlich nahe der Lover''s Lane.","facilities":"Die Restaurants auf der Insel servieren koreanische Hausmannskost (Hotteok, Süßkartoffel-Latte, Tteok-Galbi). Das Sonata Cafe in einem traditionellen Hanok ist die bekannteste Adresse. Der Ticketschalter am Fähranleger Gapyeong akzeptiert ausländische Karten — die Automaten tun das nicht, fragen Sie am Schalter.","tip":"Beste Jahreszeiten: Frühling (Kirschblüte April-Mai), Herbst (goldener Ginkgo und roter Ahorn im Oktober), Winter (Dezember-Februar, schneestille Wege wie in Winter Sonata). Meiden Sie die Fährschlange am späten Sonntagnachmittag."},"whyOnRoute":"Nami eröffnet den Tag, weil es der eine Stopp ist, den frühes Licht belohnt und Menschenmengen bestrafen. Die Metasequoien- und Ginkgo-Alleen der halbmondförmigen Insel sind ihr Markenzeichen, und sie fotografieren sich am besten vor Mittag, bevor die mit dem ITX-Zug anreisenden Individualreisenden und der Gapyeong-Stadtrundfahrtbus die zentralen Wege füllen. Nami zuerst zu setzen heißt außerdem, dass die Überfahrt in der Morgenruhe statt im Nachmittagswind stattfindet, und es legt den Rest des Tages so an, dass es landeinwärts und dann nach Hause geht, ohne zurückfahren zu müssen.","convenience":{"restroom":"Mehrere auf der Insel und am Fähranleger Gapyeong","parking":"Fähranleger Gapyeong 6,000 KRW Pkw / 10,000 KRW großes Fahrzeug"},"description":"Die Insel Nami eröffnet das zweite Kapitel des Tages mit einer 5-minütigen Fährüberfahrt vom Fähranleger Gapyeong auf eine halbmondförmige Flussinsel im Bukhan-Fluss. Namiseom misst rund **460,000 m² (140,000 Pyeong) bei ~5 km Umfang** und ist nach **General Nami (Nam Yi, 1441-1468)** benannt, einem Militärbefehlshaber der Joseon-Zeit, der mit 28 Jahren hingerichtet wurde, nachdem man ihn unter König Yejong fälschlich des Hochverrats beschuldigt hatte. \n\nUrsprünglich wurde das Gelände nur bei Hochwasser zur Insel; **1944 baute die japanische Kolonialverwaltung den Cheongpyeong-Damm, hob damit den Flusspegel und machte Nami zur dauerhaften Insel**. Weltweit bekannt wurde sie **2002 als Drehort des KBS-Dramas „Winter Sonata“** mit Bae Yong-joon und Choi Ji-woo — dem Auslöser der Hallyu-Welle der frühen 2000er — und zieht bis heute jährlich etwa **3,3 Millionen Besucher an (1,3 Millionen aus dem Ausland)**, womit sie nach Seoul, Busan und Jeju Koreas meistbesuchtes einzelnes Reiseziel ist. \n\nSeit dem **1. März 2006** vermarktet sich die Insel als selbsterklärte **„Naminara Republic“** mit eigener Flagge, eigener Währung (Nami-Tongbo-Münzen), eigenem Pass und eigener Post — ein touristisches Marketingkonzept, kein tatsächliches Staatsgebilde. \n\nDie markante **Metasequoien-Allee** (die ikonische verschneite Gasse aus „Winter Sonata“), die **Riverside Lover''s Ginkgo Tree Lane** im Süden, die **Korean Pine Road** und die aus Sojuflaschen gefertigte Recyclingglas-Brücke **Sequoia Bridge** lassen sich in entspannten zwei Stunden alle erlaufen. Zur Tierwelt der Insel gehören Pfauen (darunter seltene Albinos), Strauße, wilde Kaninchen und Eichhörnchen. \n\n**Die VISA-Gebühr der Naminara Republic (Fähre hin und zurück inklusive) ist im Tourpreis enthalten**.","visitBasics":{"hours":"Fähre ab 08:00, letzte Einfahrt um 21:00, letzte Ausfahrt um 21:05. Zwischen 09:00 und 18:00 alle 10-20 Minuten, außerhalb dieser Zeit alle 30 Minuten; die Überfahrt dauert etwa 5 Minuten. Die meisten Läden auf der Insel schließen gegen 18:00","closed":"Ganzjährig geöffnet","admission":"Visa-Gebühr der Naminara Republic, Fähre hin und zurück inklusive: Erwachsene ₩19,000 — in dieser Tour INKLUSIVE","walking":"Leicht — flache, baumbestandene Wege; die Runde über die halbe Insel misst ~3 km, die komplette Runde ~5 km. Auf der Insel können Fahrräder und E-Buggys gemietet werden, wenn Sie lieber nicht laufen möchten."},"image":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp"],"imageCredits":[{"url":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 1","alt":"Insel Nami (Namiseom) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 2","alt":"Insel Nami (Namiseom) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 3","alt":"Insel Nami (Namiseom) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"Insel Nami (Namiseom)","caption":"Insel Nami (Namiseom) — photo 4","alt":"Insel Nami (Namiseom) — gallery image 4"}]},{"number":3,"time":"≈ 12:15","duration":"60 Min.","name":"Mittagessen in Gapyeong (auf eigene Kosten)","category":"Mittagspause","description":"Nach der Insel Nami hält der Bus eine Stunde an einem lokalen Restaurant im Bereich des Fähranlegers Gapyeong. Das Mittagessen ist **nicht inklusive** — Sie bestellen und bezahlen selbst, üblicherweise ₩10,000-15,000 pro Person.\n\nDies ist Dakgalbi-Land: Der Korridor Chuncheon-Gapyeong ist die Heimat von **Dakgalbi**, süßscharfem Hähnchen, das am Tisch mit Kohl, Süßkartoffel und Reiskuchen gebraten wird und meist damit endet, dass Reis in der übrigen Sauce angebraten wird. **Makguksu** (kalte Buchweizennudeln) ist das traditionelle Begleitgericht. Vegetarische Optionen sind begrenzt, Bibimbap ist aber normalerweise verfügbar; sagen Sie es dem Guide morgens im Bus, dann ruft er vorab an.\n\nBringen Sie Bargeld oder Karte mit — die meisten Restaurants der Gegend nehmen beides, kleine Stände am Anleger jedoch oft nur Bargeld.","image":null,"highlights":[],"timeUsed":["Bus parkt, und der Guide führt die Gruppe zum Restaurant (~5 Min.)","Bestellen und essen (~45 Min.)","Einzeln bezahlen und sich am Bus wieder einfinden (~10 Min.)"],"whyOnRoute":"Das Mittagessen liegt aus zwei Gründen nach Nami und nicht davor. Erstens schützt das den Vormittag: Zuerst zu essen würde die Überfahrt über Mittag hinaus und in den Andrang schieben. Zweitens ist der Bereich um den Fähranleger Gapyeong dort, wo die Restaurants tatsächlich sind — der Garden of Morning Calm liegt an einer Talstraße mit sehr wenig drumherum, und Petite France hat vor Ort nur Imbissstände. Eine Stunde hier ist die letzte verlässliche Mahlzeit im Sitzen an diesem Tag.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"The Garden of Morning Calm","time":"≈ 13:45","number":4,"category":"Thematischer botanischer Garten","duration":"90 Min.","timeUsed":["Eintritt in den Garten und kurze Orientierung durch den Fahrer-Guide (~5 Min.)","Freie Gehzeit durch die 20 thematischen Teilgärten (~50 Min.)","Optional verlängerte Fotozeit im Sunken Garden (Form der koreanischen Halbinsel) (~10 Min.)","Im Winter: Ankunft auf den Beleuchtungsstart um 17:00 abgestimmt, um Garten bei Tag und das Anschalten des Lichterfestivals zu erleben","Wieder am Bus einfinden (~5 Min.)"],"_poi_meta":{"poi_key":"garden_of_morning_calm","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Garden of Morning Calm Official Site (morningcalm.co.kr — own corpus on founder + 1996 opening + 20 sub-gardens)","Korea Tourism Organization (VisitKorea — Lighting Festival listing + lighting-fest schedule)","Gyeonggi Cultural Foundation (ggc.ggcf.kr — official cultural promotion entry on Sunken Garden + 200,000 LEDs)","Sahmyook University Department of Horticulture (Prof. Han Sang-kyung honorary professor profile + garden origin)","Wikipedia (Garden of Morning Calm — corpus on Tagore-derived name + 5,000 species + 330,000 m² total)"]},"highlights":["Koreas bekanntestes privates Arboretum — 330,000 m² mit ~5,000 Pflanzenarten","Gegründet von Han Sang-kyung von der Sahmyook-Universität; 1996 eröffnet (1992 konzipiert)","Winterliches Lichterfestival von Dezember bis März mit über 200,000 LEDs (Koreas erstes Lichterfestival in natürlicher Umgebung)","20 thematische Teilgärten — Sunken Garden in Form der koreanischen Halbinsel, Moonlight Garden, Bonsai Garden, Garden of Eden","K-Drama-Drehort für Moonlight Drawn by Clouds und andere","**1992 konzipiert / 1994 Grundstück gekauft / 11. Mai 1996 eröffnet**: Gründer Prof. Han Sang-kyung und seine Frau entwarfen und bepflanzten den gesamten Garten persönlich und verkauften in der finanziell schweren Anfangszeit sogar ihr Haus","**Von CNN als eine von Koreas Top 50 Sehenswürdigkeiten ausgewählt** — die Form der koreanischen Halbinsel im Sunken Garden (10 große und kleine Blumenbeete als Ausdruck der Sehnsucht nach Wiedervereinigung) ist das von CNN genannte Merkmal","**Cheonnyeonhyang (Chinesischer Wacholder)** ist das offizielle Symbol des Morning Calm — die charakteristische Pflanzenart des Gartens unter den insgesamt 5,000 erfassten"],"smartNotes":{"photo":"Frühling (Kirschblüte im April), Sommer (üppiges Grün), Herbst (Laubfärbung Oktober bis Anfang November) und Winter (Lichterfestival nach Sonnenuntergang) fotografieren sich jeweils unterschiedlich. Die Lichttunnel in der Dämmerung während der Festivalzeit sind die ikonische Aufnahme.","facilities":"Der Food Garden serviert koreanische Hausmannskost (Sojabohnenpasten-Eintopf, Gemüse-Bibimbap, Snow-Cheese-Tteokbokki). Good Morning Coffee in einer Hanok-Rösterei ist das charakteristische Café. Die Restaurants schließen um 20:00.","tip":"Für das Lichterfestival (5. Dez. - 15. März) erwischt die Ankunft um 17:00 sowohl die Farben des Gartens bei Tag als auch das Anschalten der Beleuchtung. Starker Schneefall im Februar ergibt die märchenhafteste Frozen-Kulisse."},"whyOnRoute":"Der Garden of Morning Calm — der „Garten der Morgenstille“ — ist das mittlere und ruhigste Kapitel des Tages: 90 Minuten reichen, um die Hauptrunde am Sunken Garden mit seinen Blumenbeeten in Form der koreanischen Halbinsel entlangzugehen und sich trotzdem irgendwo hinzusetzen. Der Garten liegt landeinwärts und oberhalb des Flusses, also muss er nach Nami und vor der Heimfahrt kommen; ein Besuch am frühen Nachmittag erwischt den Garten außerdem in seiner wärmsten Phase, was von November bis März zählt, wenn die Kälte im Tal hängen bleibt.","convenience":{"restroom":"Mehrere, ausgeschildert","parking":"Großer kostenloser Busparkplatz; Münzschließfächer 1,500-2,000 KRW (nur 500-KRW-Münzen)"},"description":"Rund 30 Minuten südlich der Insel Nami liegt der Garden of Morning Calm, **Koreas bekanntestes privates Arboretum** — etwa **330,000 m²** gestaltete Landschaft mit rund **5,000 Pflanzenarten**. **1992** konzipiert und **1996** für die Öffentlichkeit geöffnet, wurde der Garten von **Han Sang-kyung von der Sahmyook-Universität** entworfen und persönlich bepflanzt; er verkaufte zeitweise sein Haus, um das Projekt zu finanzieren. Der Name greift Koreas alten Beinamen „**Land of the Morning Calm**“ (Land der Morgenstille, Joseon) auf. \n\n**Zwanzig thematische Teilgärten** — darunter der **Sunken Garden in Form der koreanischen Halbinsel**, der Hometown House Garden, der Bonsai Garden, der Moonlight Garden, der Sky Path und der Garden of Eden — haben jeweils eine eigene visuelle Handschrift und dienten als Kulisse für viele K-Dramen, unter anderem **Moonlight Drawn by Clouds**. \n\nVon Anfang Dezember bis Mitte März richtet der Garten jeden Winter **Koreas erstes Lichterfestival in natürlicher Umgebung** aus, mit mehr als **200,000 umweltfreundlichen LED-Lampen** auf dem gesamten Gelände, die den Garten nach Sonnenuntergang in ein Winterwunderland verwandeln. \n\n**Der Name „Garden of Morning Calm“** geht auf den indischen Dichter Rabindranath Tagore zurück, der Korea 1929 als „Land of Morning Calm“ bezeichnete. Han Sang-kyung fasste die Idee 1992, während er als Austauschprofessor in den Vereinigten Staaten arbeitete und sich dort von erstklassigen Privatgärten inspirieren ließ. \n\n**Han und seine Frau entwarfen den Garten und arbeiteten persönlich daran**, und in finanziell schwierigen Phasen verkauften sie ihr Wohnhaus und lebten in einer kleinen Unterkunft auf dem Gartengelände, um den Bau fortzusetzen. \n\nDer Garten öffnete am 11. Mai 1996 erstmals für die Öffentlichkeit, mit 10 thematischen Bereichen; heute ist er auf 20 thematische Teilgärten über 330,000 m² angewachsen. **Der Eintritt ist im Tourpreis INKLUSIVE**.","visitBasics":{"hours":"Etwa 08:30 bis Sonnenuntergang (üblicherweise 08:30-19:00), letzter Einlass 18:00. Während des winterlichen Lichterfestivals bleibt der Garten bis in den Abend geöffnet — die Zeiten wechseln mit der Saison, und der Guide bestätigt die Schließzeit des Tages im Bus","closed":"Ganzjährig geöffnet","admission":"Erwachsene ₩11,000 — in dieser Tour INKLUSIVE","walking":"Mittel — weitläufige Wege über welliges Gelände durch die thematischen Teilgärten; die Hauptrunde ist weitgehend kinderwagentauglich"},"image":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","images":["/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp"],"imageCredits":[{"url":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","source":"atoc-korea"},{"url":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/garden-of-morning-calm/garden-of-morning-calm-flowers.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 1","alt":"The Garden of Morning Calm — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-36-31.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 2","alt":"The Garden of Morning Calm — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-10-10-43-58.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 3","alt":"The Garden of Morning Calm — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/garden-of-morning-calm/chatgpt-image-2026-5-11-01-09-33.webp","location":"The Garden of Morning Calm","caption":"The Garden of Morning Calm — photo 4","alt":"The Garden of Morning Calm — gallery image 4"}]},{"number":5,"time":"≈ 16:00","duration":"60 Min.","name":"Petite France","category":"Themendorf zu „Le Petit Prince“","description":"Der kompakte Schlussstopp des Tages: Petite France ist ein französisches Kulturthemendorf, das etwa 25 Minuten von der Insel Nami entfernt in einen Hang oberhalb des Cheongpyeong-Sees gebaut wurde. Im Juli 2008 vom Gründer Han Hong-seop eröffnet, ist das Dorf aus 16 Gebäuden dem Motto „Blumen, Sterne und der kleine Prinz“ gewidmet (nach Antoine de Saint-Exupérys Roman Le Petit Prince von 1943) und beherbergt eine Saint-Exupéry-Gedenkhalle, das Orgel House (eine Sammlung antiker Spieldosen mit einem 200 Jahre alten Prunkstück, das noch spielt), eine Ausstellung französischen Wohnens, ein Marionettentheater und eine Galerie mit Skulpturen und Bildern des le coq gaulois (des gallischen Hahns). \n\nDrama-Fans kommen vor allem wegen des K-Drama-Erbes: Petite France war Drehort für Beethoven Virus (2008), Personal Taste (2010), Secret Garden (2010), My Love from the Star (2013-2014), den Erfolg Bon Appétit Your Majesty von 2025 (die Maison de Marie diente als Zimmer der von Im Yoon-ah gespielten Figur) und die beliebte Unterhaltungsshow Running Man. \n\nDas benachbarte Pinocchio & Da Vinci Italian Village bietet Gästen mit mehr Zeit ein Kombiticket an. Der Ort wurde für das Programm zum 140. Jubiläum der Beziehungen zwischen Korea und Frankreich 2026 ausgewählt. \n\nDas Dorf hat eine Doppelfunktion: französisches Kulturthemendorf + das **Goseong Youth Training Center**, das bis zu 200 Gäste in Zimmern für 4 bis 10 Personen zu Bildungsaufenthalten unterbringt. \n\nDas architektonisch auffälligste Element der Anlage ist die **Traditional France Residence Gallery**: ein komplettes französisches Bauernhaus des 19. Jahrhunderts aus Mittelfrankreich, abgebaut und vor Ort mit über 200 Jahre altem Holz, Dachziegeln und Ziegelsteinen wieder aufgebaut — vollständig ohne Nägel gefügt, in traditioneller französischer Fachwerktechnik mit Zapfen und Zapfenloch. \n\nPetite France ist außerdem **Koreas einzige von der Saint-Exupéry-Stiftung lizenzierte Einrichtung**, das heißt jedes Motiv des kleinen Prinzen vor Ort ist offiziell von der Stiftung in Frankreich autorisiert. \n\nDas benachbarte Pinocchio & Da Vinci Italian Village (separates Ticket oder Kombiticket zu ₩19,500 für Erwachsene) verlängert das europäische Dorfprogramm des Tages auf Wunsch um rund 45 Min.","highlights":["Eröffnet im Juli 2008; 16 Gebäude im französischen Stil rund um das Thema „Der kleine Prinz“ (Saint-Exupéry, 1943)","K-Drama-Drehorte: Beethoven Virus (2008), Personal Taste (2010), Secret Garden (2010), My Love from the Star (2013-14), Bon Appétit Your Majesty (2025)","Orgel House: 200 Jahre alte Spieldosensammlung; Marionettentheater mit täglichen Vorstellungen","Benachbartes Pinocchio & Da Vinci Italian Village — Kombitickets 19,500 KRW für Erwachsene","Ausgewählt für das Programm zum 140. Jubiläum der Beziehungen zwischen Korea und Frankreich 2026","**Koreas einzige Einrichtung mit internationalem Lizenzvertrag mit der Saint-Exupéry-Stiftung in Frankreich** — jedes Motiv des kleinen Prinzen vor Ort ist offiziell lizenziert","**Unter den 16 Gebäuden ist ein französisches Bauernhaus des 19. Jahrhunderts**, wieder aufgebaut aus über 200 Jahre altem Holz, Dachziegeln und Ziegelsteinen aus Mittelfrankreich, ohne Nägel gefügt (traditionelle französische Fachwerkbauweise)","**Drehort des K-Dramas „Bon Appétit, Your Majesty“ von 2025**: Die „Maison de Marie“ dient als heutige koreanische Wohnung von Yeon Ji-yeong (IM YOON-AH) — eine Ergänzung des bestehenden K-Drama-Portfolios (Beethoven Virus 2008, Personal Taste 2010, Secret Garden 2010, My Love from the Star 2013, Vincenzo 2021)"],"timeUsed":["Eintritt und kurze Orientierung","Gang durch die farbigen Gassen und die 16 Gebäudeausstellungen + Fotopunkte (~45 Min.)","Optional Marionettenvorstellung oder Spieldosen-Vorführung, sofern angesetzt","Kleine Stärkung an den Imbissständen oder im Café vor Ort","Optionaler Anschlussbesuch im Pinocchio & Da Vinci Italian Village (~45 Min., Kombiticket ₩19,500 für Erwachsene)"],"whyOnRoute":"Petite France beschließt den Tag wegen seiner Lage, nicht nur wegen seines Charakters: Das Dorf liegt am Ufer des Cheongpyeong-Sees und damit bereits in Richtung Seoul, sodass eine Stunde hier keine zusätzliche Fahrzeit kostet. Es ist außerdem mit Abstand der kleinste Stopp des Tages — sechzehn Gebäude an einem Hang, in unter einer Stunde erlaufen —, was nach zwei Stunden auf einer Insel und neunzig Minuten in einem Garten den richtigen Schlusston setzt. Fans von My Love from the Star, Secret Garden und Beethoven Virus erkennen es sofort wieder.","visitBasics":{"hours":"09:00-18:00, letzter Einlass 17:00; die Schließzeit verschiebt sich mit der Saison und an manchen Abenden wegen geplanter Nachtveranstaltungen","closed":"Ganzjährig geöffnet","admission":"Erwachsene ₩12,000 — in dieser Tour INKLUSIVE. Das Kombiticket mit dem benachbarten Pinocchio & Da Vinci Italian Village (₩19,500 für Erwachsene) ist NICHT enthalten; die Stunde in diesem Programm gilt nur für Petite France","walking":"Leicht — ein kleines Dorf an einem sanften Hang, in unter einer Stunde bequem zu erlaufen"},"convenience":{"restroom":"Vor Ort","parking":"Kostenlose Parkplätze"},"smartNotes":{"photo":"Die pastellfarbenen Fachwerkhäuser vor der grünen Bergkulisse sind die charakteristischen Aufnahmen. Die Aussichtsplattform oben am Hang bietet die beste Weitwinkelkomposition. Das Aufspüren von K-Drama-Szenen ist für Fans eine geführte Aktivität (Saint-Exupéry-Gebäude = Schlüsselszenen aus My Love from the Star).","facilities":"Nur Imbissstände — Waffeln, Teigtaschen, Fischkuchensuppe, Kaffee. Die meisten Gäste essen stattdessen im benachbarten Italian Village oder im nahen Ort Cheongpyeong.","tip":"Auf eigene Faust am besten mit der Insel Nami und/oder dem Garden of Morning Calm über den Gapyeong City Tour Bus zu verbinden. Eine Ankunft am späten Nachmittag lässt Sie Tageslicht und frühe Abendbeleuchtung sehen. Gäste, die eine große Attraktion erwarten, merken oft den bescheidenen Zuschnitt an (üblich sind 1,5-2 Stunden) — Erwartungen entsprechend steuern."},"_poi_meta":{"poi_key":"petite_france","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","note":"POI verified in KB v1.10 (Batch 7) and reused here unchanged.","sources":["Petite France Official Site (en.pfcamp.com — own corpus on founder + 16-building layout + Goseong Youth Training Center)","Korea Tourism Organization (VisitKorea — Petite France listing + 2025 ''Bon Appétit, Your Majesty'' filming-location verification)","Saint-Exupéry Foundation France (international license agreement — Le Petit Prince motif authorization)","Gapyeong County Tourism Office (gapyeong.go.kr — official local-government attractions listing)","Wikipedia (Petite France theme park — corpus on July 2008 opening + Le Petit Prince theme + organizational structure)"]},"image":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","images":["/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","/images/tours/petite-france/petite-france-couple-colorful.webp","/images/tours/petite-france/petite-france-ai-pastel-village.webp"],"imageCredits":[{"url":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","source":"atoc-korea"},{"url":"/images/tours/petite-france/petite-france-couple-colorful.webp","source":"atoc-korea"},{"url":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/petite-france/kakaotalk-20260510-222949305-02.webp","location":"Petite France","caption":"Petite France — photo 1","alt":"Petite France — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/petite-france/petite-france-couple-colorful.webp","location":"Petite France","caption":"Petite France — photo 2","alt":"Petite France — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/petite-france/petite-france-ai-pastel-village.webp","location":"Petite France","caption":"Petite France — photo 3","alt":"Petite France — gallery image 3"}]},{"number":6,"time":"≈ 18:30","duration":"≈ 1,5 Stunden Fahrt","name":"Rückfahrt nach Seoul (Station Myeongdong oder Bahnhof Hongik University)","category":"Rückfahrt und Ausstieg","description":"Die Abfahrt in Petite France ist gegen 16:45 für die rund 1,5-stündige Fahrt zurück nach Seoul auf der Schnellstraße Seoul-Chuncheon. Die Ausstiege erfolgen in umgekehrter Reihenfolge der Abholung: **Station Myeongdong gegen 18:30**, dann **Bahnhof Hongik University gegen 19:00**.\n\nBeide sind U-Bahn-Umsteigepunkte, sodass Anschlüsse unkompliziert sind, und die Zeitplanung lässt den Abend frei — Sie sind deutlich zurück, bevor Seouls Restaurants voll werden. Freitagabende und Rückfahrten am Sonntag können auf der Einfahrt in die Stadt 20-40 Minuten Verkehr hinzufügen; der Guide gibt unterwegs die aktuelle Schätzung des Busses durch.","image":null,"highlights":[],"timeUsed":["Abfahrt in Petite France (~16:45)","Fahrt über die Schnellstraße mit einem kurzen Zwischenstopp bei Bedarf (~1,5 Stunden)","Ausstieg Station Myeongdong (~18:30)","Ausstieg Bahnhof Hongik University (~19:00)"],"whyOnRoute":"Dass der Tag in Petite France endet und nicht im Garden of Morning Calm, hält die Rückfahrt kurz: Das Dorf liegt bereits auf der Seouler Seite von Gapyeong, der Bus ist also von der Abfahrt an heimwärts gerichtet. Die umgekehrte Ausstiegsreihenfolge bedeutet, dass die Gäste aus Myeongdong, die zuletzt eingestiegen sind, zuerst aussteigen.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}],"routeFlowStops":[{"name":"Abholung (Hongik / Myeongdong)","type":"origin","theme":"Seoul pickup"},{"name":"Insel Nami","type":"primary","theme":"K-drama island"},{"name":"Mittagessen in Gapyeong","type":"secondary","theme":"Lunch break"},{"name":"The Garden of Morning Calm","type":"primary","theme":"Themed garden"},{"name":"Petite France","type":"primary","theme":"French village"},{"name":"Rückfahrt nach Seoul","type":"return","theme":"Drop-off"}],"routePhases":[{"phase":"Seoul → Gapyeong","duration":"≈ 1,5 Stunden","description":"Abholung um 07:30 an der Hongik University bzw. um 08:00 in Myeongdong, dann eine rund 1,5-stündige Fahrt nach Nordosten zum Fähranleger Gapyeong und die fünfminütige Überfahrt zur Insel Nami."},{"phase":"Insel Nami","duration":"≈ 2 Stunden","description":"Flache, baumbestandene Alleen, die Metasequoien-Allee aus „Winter Sonata“, Bänke am Fluss sowie frei laufende Strauße und Pfauen. Die Hin- und Rückfahrt mit der Fähre und die Visa-Gebühr der Naminara Republic sind inklusive."},{"phase":"Mittagessen → Garden of Morning Calm","duration":"≈ 2,5 Stunden","description":"Mittagessen in einem lokalen Restaurant in Gapyeong (auf eigene Kosten — Dakgalbi-Land), dann rund 35 Minuten landeinwärts und bergauf zum Garden of Morning Calm für 90 Minuten in dessen thematischen Teilgärten."},{"phase":"Petite France → Seoul","duration":"≈ 2,5 Stunden","description":"Rund 45 Minuten zurück hinunter ans Ufer des Cheongpyeong-Sees für eine Stunde in Petite France, dann die rund 1,5-stündige Fahrt nach Seoul — Myeongdong gegen 18:30, Hongik gegen 19:00."}],"routeShapeIntro":{"title":"So verläuft dieser Tag ab Seoul","subtitle":"Abholung um 07:30 an der Hongik University bzw. um 08:00 in Myeongdong und eine rund 1,5-stündige Fahrt nach Nordosten bringen Sie auf die Fähre zur Insel Nami, bevor der Tagesausflugsandrang dichter wird. Mittagessen im Ort Gapyeong, dann dreht die Route landeinwärts und steigt zum Garden of Morning Calm hinauf, um schließlich wieder hinunter nach Petite France am Ufer des Cheongpyeong-Sees zu führen — das ohnehin auf dem Heimweg liegt, sodass der letzte Stopp keinen Umweg kostet. Zurück in Seoul gegen 18:30-19:00."},"whyTourWorks":{"bestFor":["Erstbesucher, die Koreas Landschaft ohne Bergwanderung sehen möchten","Paare und Hallyu-Fans, die wegen der Metasequoien-Allee aus „Winter Sonata“ kommen","Familien und ältere Reisende — jeder Stopp ist flach oder sanft hügelig","Alle, die einen ganzen Tag außerhalb Seouls wollen, der trotzdem vor dem Abendessen endet"],"lessIdealFor":["Wanderer — auf dieser Route gibt es weder Berg noch Gipfel","Reisende, die lieber einen einzigen ruhigen Stopp hätten statt drei","Gäste, die vor 19:00 Nachtleben oder Zeit in der Stadt am Abend erwarten"],"routeLogicSections":[{"title":"Tempo & Geografie","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Nami zuerst, vor dem Andrang","detail":"Gapyeong liegt nur rund 75 km von Seoul entfernt, sodass eine Abfahrt um 07:30 den Anleger gegen 10:00 erreicht — vor den Individualreisenden, die mit den ITX-Zügen am späten Vormittag ankommen, und noch im tiefen Morgenlicht auf der Metasequoien-Allee."},{"label":"Die Gärten liegen landeinwärts, das Dorf liegt auf dem Heimweg","detail":"Der Garden of Morning Calm liegt oben in Sang-myeon, rund 35 Minuten landeinwärts vom Fluss; Petite France liegt wieder unten am Ufer des Cheongpyeong-Sees und damit bereits Richtung Seoul. In dieser Reihenfolge kostet der letzte Stopp keinen Umweg."},{"label":"Drei Eintritte, ein Preis","detail":"Namis Visa-Gebühr von ₩19,000 (Fähre hin und zurück inklusive), die ₩11,000 des Garden of Morning Calm und die ₩12,000 für Petite France sind alle abgedeckt — rund ₩42,000 an Eintritten, für die Sie weder anstehen noch erneut zahlen."},{"label":"Ein kürzerer Tag als die Seoraksan-Routen","detail":"Weil hier nichts in Gangwon liegt, ist der Bus etwa drei statt fünf Stunden unterwegs. Genau deshalb wirkt dieser Tag entspannt, wo die Seoraksan-Programme lang wirken."}]}]},"practicalAccordionItems":[{"id":"pickup","title":"Abholung & Ausstieg","preview":"Zwei Abholpunkte in Seoul: Starbucks am Bahnhof Hongik University, Ausgang…","content":["Zwei Abholpunkte in Seoul: Starbucks am Bahnhof Hongik University, Ausgang 8, um 07:30 (Mapo-gu) und Station Myeongdong, Ausgang 2, beim NorthFace-Flagshipstore, um 08:00 (Jung-gu).","Beide Abholungen teilen sich denselben Bus; bitte seien Sie 5 Minuten früher an Ihrem gewählten Punkt.","Ausstiege in umgekehrter Reihenfolge: Myeongdong ≈18:30, Hongik University ≈19:00.","Ihre tatsächliche Tourdauer hängt vom Abholpunkt ab: ≈11,5 Stunden ab Hongik, ≈10,5 Stunden ab Myeongdong."]},{"id":"what-to-bring","title":"Kleidung & Ausrüstung","preview":"Bequeme Schuhe zum Gehen — Wanderschuhe sind nicht nötig, aber Sie sind übe…","content":["Bequeme Schuhe zum Gehen — Wanderschuhe sind nicht nötig, aber Sie sind über den Tag 5-6 km auf den Beinen.","Warme Kleidung im Zwiebelprinzip von November bis März; die Täler um Gapyeong sind mehrere Grad kälter als das Zentrum Seouls, und das Deck der Nami-Fähre ist ungeschützt.","Kamera oder Smartphone — die Metasequoien-Allee auf Nami und der Aussichtspunkt am Sunken Garden im Morning Calm sind die beiden Aufnahmen, für die Leute kommen.","Bargeld und Karte für das Mittagessen (₩10,000-15,000) und mögliche Extras.","Sonnenschutz im Sommer; die Gartenrunde hat lange Abschnitte mit wenig Schatten."]},{"id":"weather-policy","title":"Wetterregelung","preview":"Ganzjähriger Betrieb.","content":["Ganzjähriger Betrieb.","Leichter Regen: Die Tour läuft wie geplant. Alle drei Stopps halten Regen stand — Namis Baumalleen und der Garden of Morning Calm sind bei nassem Wetter beide wirklich schön, und Petite France hat Ausstellungsräume im Innenbereich.","Starkregen oder Sturm: Die Nami-Fähre kann bei schwerem Wetter ausgesetzt werden. Passiert das, verlängert der Guide die Stopps im Garten und in Petite France, und der Nami-Eintritt wird erstattet.","Schnee: In Gapyeong fällt mehr Schnee als im Zentrum Seouls. Der Bus fährt in der Saison mit Winterreifen; starker Schneefall kann die Rückfahrt um eine Stunde verlängern.","Reihenfolge oder Zeiten des Programms können sich am Tag wegen Verkehr, Wetter oder Öffnungszeiten verschieben — der Guide bestätigt den Tagesplan im Bus."]},{"id":"inclusions","title":"Was inklusive ist","preview":"Zwei Abholpunkte in Seoul und dieselben zwei Ausstiegspunkte, klimatisierte…","content":["Zwei Abholpunkte in Seoul und dieselben zwei Ausstiegspunkte, klimatisierter Bus, lizenzierter englischsprachiger Guide.","Fähre hin und zurück zur Insel Nami + Visa-Gebühr der Naminara Republic (₩19,000) — INKLUSIVE.","Eintritt in den Garden of Morning Calm (₩11,000) — INKLUSIVE.","Eintritt Petite France (₩12,000) — INKLUSIVE.","Maut- und Parkgebühren — INKLUSIVE.","NICHT inklusive: Mittagessen und Getränke (₩10,000-15,000, auf eigene Kosten), das Kombiticket Petite France + Italian Village (₩19,500), Fahrrad- oder E-Buggy-Miete auf der Insel Nami, die Skyline-Zipwire nach Nami sowie persönliche Ausgaben.","Chinesischsprachiger Guide auf Anfrage verfügbar — bitte mindestens 3 Tage im Voraus buchen."]},{"id":"language","title":"Sprache","preview":"Hauptsprache der Tour: Englisch.","content":["Hauptsprache der Tour: Englisch.","Chinesischsprachiger Guide auf Anfrage verfügbar — mindestens 3 Tage im Voraus buchen.","Vor Ort wird den ganzen Tag Koreanisch gesprochen, auf Speisekarten, Schildern und an Ständen; der Guide übernimmt die Übersetzung."]},{"id":"walking","title":"Gehen & Gelände","preview":"Leicht bis mittel — diese Route enthält keine Wanderung und keine treppenla…","content":["Leicht bis mittel — diese Route enthält keine Wanderung und keine treppenlastigen Abschnitte.","Insel Nami: flache, gepflasterte, baumbestandene Alleen; ~3 km in 2 Stunden ist das übliche Tempo. Fahrräder und E-Buggys können auf der Insel auf eigene Kosten gemietet werden.","Garden of Morning Calm: welliges Gelände auf überwiegend gepflasterten Gartenwegen; die Hauptrunde ist weitgehend kinderwagentauglich, einige thematische Teilgärten liegen jedoch kurze Steigungen hinauf.","Petite France: ein kleines Hangdorf, sanfte Steigungen, in unter einer Stunde in entspanntem Tempo.","Insgesamt kommen über den Tag etwa 5-6 km zusammen, verteilt auf drei Stopps mit dem Bus dazwischen. Bequeme Schuhe genügen — Wanderschuhe sind nicht nötig."]},{"id":"lunch","title":"Mittagessen (auf eigene Kosten)","preview":"Das Mittagessen findet gegen 12:15 in einem lokalen Restaurant im Bereich d…","content":["Das Mittagessen findet gegen 12:15 in einem lokalen Restaurant im Bereich des Fähranlegers Gapyeong statt, nach der Insel Nami.","Dies ist Dakgalbi-Land — süßscharfes Hähnchen, am Tisch gebraten und meist damit beendet, dass Reis in der Sauce angebraten wird. Makguksu (kalte Buchweizennudeln) ist das klassische Begleitgericht.","Rechnen Sie mit etwa ₩10,000-15,000 pro Person. Bargeld und Karte werden normalerweise beide akzeptiert; Stände am Anleger nehmen oft nur Bargeld.","Vegetarische Optionen sind in dieser Region begrenzt — sagen Sie es dem Guide morgens, dann ruft er vorab an."]},{"id":"cancellation","title":"Stornierung","preview":"Kostenlose Stornierung bis 24 Stunden vor der Abholung.","content":["Kostenlose Stornierung bis 24 Stunden vor der Abholung.","Innerhalb von 24 Stunden: 50% Erstattung.","Nichterscheinen oder verpasste Abholung: keine Erstattung — kontaktieren Sie aber innerhalb von 10 Minuten nach der Abholzeit die Betriebsleitung von AtoC Korea, der Bus kann kurz warten, wenn er der Zeit voraus ist."]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"Siehe saisonale Hinweise"},"tomorrow":{"temp":"—","label":"Siehe saisonale Hinweise"},"_seasonalSummary":"Seoul + Gangwon: temperate four-season climate. Seoraksan is 5-7°C cooler than Seoul year-round. Hot humid summers (Jun-Aug), crisp cold winters (Dec-Feb), with prime seasons in spring (April cherry blossoms) and autumn (October-November foliage)."},"seasonalVariations":[{"season":"Frühling (März-Mai)","description":"Kirschblüte am Bukhan-Fluss Anfang April, dann das Frühlingsfestival des Garden of Morning Calm mit Zehntausenden Tulpen. Petite France'' pastellfarbene Gebäude wirken vor frischem Grün am besten."},{"season":"Sommer (Juni-August)","description":"Namis Baumalleen spenden echten Schatten, und die Insel ist merklich kühler als Seoul. Der Garten ist üppig, aber heiß und weitgehend unbeschattet — Wasser und Sonnenschutz mitnehmen. Im Juli-Monsun sind Schauer am Nachmittag zu erwarten."},{"season":"Herbst (September-November)","description":"Die stärkste Saison auf dieser Route. Namis Metasequoien- und Ginkgo-Alleen färben sich von Ende Oktober bis Mitte November, und der Garden of Morning Calm zeigt seine herbstliche Chrysanthemenschau. Früh buchen — das ist die Zeit der höchsten Nachfrage."},{"season":"Winter (Dezember-Februar)","description":"Das Lichterfestival des Garden of Morning Calm beleuchtet das Gelände von Anfang Dezember bis etwa Mitte März, und der Garten bleibt währenddessen bis in den Abend geöffnet. Nami unter Schnee ist das Bild aus „Winter Sonata“ selbst. Ziehen Sie sich richtig an — die Täler sind kalt und das Fährdeck ist ungeschützt."}],"bookingTrustItems":[{"icon":"check-circle","title":"Alle Eintritte inklusive","description":"Nami-Fähre + Morning Calm im Paket","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"Die Fähre zur Insel Nami (₩19,000) und der Eintritt in den Garden of Morning Calm (₩11,000) sind im Tourpreis vorab bezahlt — kein Anstehen an den einzelnen Stopps. Der Eintritt am Seoraksan ist KOSTENLOS (im Mai 2023 abgeschafft). Ersparnis bei den Eintritten insgesamt: ~₩30,000."},{"icon":"users","title":"Lizenzierter englischsprachiger Guide","description":"In Korea lizenzierter Reiseleiter","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"Von der Korea Tourism Organization lizenzierter Guide mit fließendem Englisch; chinesischsprachiger Guide auf vorherige Anfrage verfügbar. Die Erläuterungen umfassen die Tempelgeschichte des Seoraksan aus der Silla-Zeit, Namis Winter-Sonata-Erbe und die Gründergeschichte des Morning Calm."},{"icon":"shield","title":"Transparente Preise","description":"Keine versteckten Shoppingstopps","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"Keine Ginsengläden, kein Duty-free, keine Souvenirumwege auf Provision. Jede Minute des 13-stündigen Tages findet an einer Sehenswürdigkeit oder auf der Fahrt statt — was Sie buchen, ist das, was Sie erleben."}],"bookingSupportSteps":[{"timing":"Sofort","title":"Sofortige Bestätigung","detail":"Buchungsbestätigung mit Auswahl des Abholpunkts","description":"Sofortige Buchungsbestätigung mit Auswahl des Abholpunkts Hongik oder Myeongdong."},{"timing":"Am Vortag","title":"Abholdetails","detail":"Genauer Abholort und Fahrzeuginfos per WhatsApp/SMS","description":"Wettercheck, Kennzeichen des Busses und etwaige saisonale Hinweise zur Route (Zeitpunkt des Lichterfestivals im Morning Calm, Laubfärbungshöhepunkt am Seoraksan usw.) werden am Vortag verschickt."},{"timing":"Am Morgen","title":"Abholbestätigung","detail":"Guide am Abholpunkt 10 Min. vor Abfahrt erkennbar","description":"Der Guide wartet am Starbucks an Ausgang 8 in Hongik ab 05:50; an Ausgang 2 in Myeongdong (NorthFace) ab 06:20. Ein Foto des Guides und des Busses wird Ihnen am Vorabend per WhatsApp geschickt."},{"timing":"Während der Tour","title":"Betreuung während der Tour","detail":"Erläuterungen an jedem Stopp + Support rund um die Uhr","description":"Der Guide erläutert vor Ort die Gründung des Seoraksan-Tempels im Jahr 652 in der Silla-Zeit, Namis Entstehung durch den Cheongpyeong-Damm 1944 und das Winter-Sonata-Erbe von 2002 sowie die Konzeption des Morning Calm 1992 und seine Eröffnung 1996."},{"timing":"Am Ende des Tages","title":"Zwei Ausstiegspunkte","detail":"Myeongdong ~19:00 / Hongik ~19:30","description":"Der Bus hält auf der Rückfahrt an beiden Abholpunkten in umgekehrter Reihenfolge."},{"timing":"Nach der Tour","title":"Bewertung & Nachbereitung","detail":"Optionale Bewertung nach der Tour","description":"Eine Bitte um Rückmeldung wird nach der Tour verschickt; Empfehlungen für Restaurants oder Sehenswürdigkeiten für den Rest Ihres Aufenthalts in Seoul beantworten wir am selben Tag."}],"staticQuestions":[{"question":"Sind wirklich alle Eintritte inklusive?","answer":"Ja — die drei Eintritte auf dieser Route sind alle abgedeckt: die Visa-Gebühr der Naminara Republic von ₩19,000 für die Insel Nami (inklusive Fähre hin und zurück), die ₩11,000 des Garden of Morning Calm und die ₩12,000 für Petite France. Das sind rund ₩42,000 pro Erwachsenem, für die Sie weder anstehen noch erneut zahlen. Das Mittagessen ist der wesentliche Posten, den Sie selbst tragen."},{"question":"Ist das dasselbe wie die Seoraksan-Tour, die auch Nami und Morning Calm besucht?","answer":"Nein, und der Unterschied sind etwa drei Stunden Fahrt. Die Seoraksan-Tagestour ergänzt einen Nationalpark in Gangwon-do, was einen Start um 06:00, fünf Stunden auf der Straße und einen 13-Stunden-Tag bedeutet. Diese Tour bleibt in Gapyeong: Start um 07:30, etwa drei Stunden Fahrt und Petite France anstelle des Bergs. Wählen Sie diese, wenn Sie die Gärten und die Insel ohne die Buszeit möchten."},{"question":"Wie viel wird gelaufen?","answer":"Etwa 5-6 km über den ganzen Tag, aufgeteilt auf drei getrennte Stopps mit dem Bus dazwischen. Es gibt keine Wanderung, keinen Gipfel und keine langen Treppenaufstiege. Nami ist völlig flach, der Garden of Morning Calm ist sanft wellig, und Petite France ist ein kleines Hangdorf. Bequeme Alltagsschuhe genügen."},{"question":"Ist das für kleine Kinder oder ältere Reisende geeignet?","answer":"Ja, mehr als die meisten Tagesausflüge ab Seoul. Jeder Stopp ist flach oder sanft geneigt, die längste einzelne Fahrt dauert etwa 1,5 Stunden, und der Tag endet um 19:00. Auf Nami gibt es Fahrräder und E-Buggys zu mieten, falls die Insel zu Fuß zu viel ist, und die Hauptrunde des Garden of Morning Calm ist weitgehend kinderwagentauglich. Der eine Vorbehalt ist die Gesamtlänge des Tages — es sind trotzdem 11 Stunden von Tür zu Tür."},{"question":"Was ist die Visa-Gebühr der Naminara Republic?","answer":"Es ist das Eintrittsticket der Insel Nami, gestaltet als Visum, weil sich die Insel 2006 als kulturtouristisches Konzept zur „Naminara Republic“ erklärt hat — samt eigener Flagge, Briefmarken und Einreiseschalter. Praktisch ist es ein Erwachsenenticket für ₩19,000, das die fünfminütige Fährüberfahrt in beide Richtungen einschließt, und es ist in dieser Tour enthalten."},{"question":"Können wir das Italian Village neben Petite France besuchen?","answer":"Nicht in diesem Programm. Das Pinocchio & Da Vinci Italian Village liegt auf dem Hügel direkt hinter Petite France und erfordert ein Kombiticket (₩19,500 für Erwachsene) sowie mindestens eine weitere Stunde. Diese Tour enthält nur Petite France und sieht dort eine Stunde vor. Wenn Ihnen das Italian Village wichtig ist, kann unsere private Gapyeong-Tour es einbauen."},{"question":"Was passiert, wenn es regnet?","answer":"Die Tour läuft. Alle drei Stopps funktionieren bei leichtem Regen — Namis baumbestandene Alleen und der Garten sind nass wirklich stimmungsvoll, und Petite France hat Ausstellungsräume im Innenbereich, darunter die Saint-Exupéry-Halle und das Orgel House. Das einzige echte Wetterrisiko ist ein Sturm, der die Nami-Fähre aussetzt; in diesem Fall verlängert der Guide die beiden anderen Stopps, und der Nami-Eintritt wird erstattet."},{"question":"Ist das Lichterfestival im Garden of Morning Calm inklusive?","answer":"Das Festival ist kein separates Ticket — es findet innerhalb des Gartens statt, und Ihr enthaltener Eintritt deckt es ab. Dies ist aber ein Tagesprogramm: Wir sind am frühen Nachmittag im Garten, in der Festivalsaison von Dezember bis März sehen Sie die Installationen also unbeleuchtet statt illuminiert. Wenn der beleuchtete Garten Ihre Priorität ist, sagen Sie es uns, und wir weisen Ihnen stattdessen eine Abendoption."},{"question":"Welche K-Dramen wurden an diesen Stopps gedreht?","answer":"Die Insel Nami ist der Drehort von Winter Sonata (2002) — die Metasequoien-Allee ist die Szene, in der die Leute stehen wollen. Zu den Credits von Petite France zählen Beethoven Virus (2008), Personal Taste (2010), Secret Garden (2010) und My Love from the Star (2013-14). Auch der Garden of Morning Calm diente als Drehort, unter anderem für Moonlight Drawn by Clouds."},{"question":"Wann sind wir zurück in Seoul?","answer":"Station Myeongdong gegen 18:30 und Bahnhof Hongik University gegen 19:00. Beide sind U-Bahn-Umsteigepunkte. Freitagabende und Rückfahrten am Sonntag können auf der Einfahrt in die Stadt 20-40 Minuten hinzufügen — der Guide gibt unterwegs eine aktuelle Schätzung durch. Die Zeitplanung ist bewusst früh genug, um Ihren Abend frei zu lassen."},{"question":"Ist das Mittagessen inklusive?","answer":"Nein. Der Bus hält eine Stunde an einem Restaurant im Bereich des Fähranlegers Gapyeong, und Sie bestellen und bezahlen selbst, üblicherweise ₩10,000-15,000. Dies ist die Heimatregion von Dakgalbi — süßscharfes Hähnchen, am Tisch gebraten —, das meist mit Makguksu-Nudeln gegessen wird. Vegetarische Auswahl ist begrenzt, sagen Sie es also dem Guide morgens, dann ruft er vorab an."},{"question":"Gibt es einen Guide, und in welcher Sprache?","answer":"Ja — ein lizenzierter englischsprachiger Guide begleitet den Bus den ganzen Tag. Ein chinesischsprachiger Guide ist auf Anfrage verfügbar, wenn Sie mindestens drei Tage im Voraus buchen. Die Stopps selbst sind weitgehend selbstbestimmt: Der Guide kümmert sich um Eintritt, Zeitplanung, Orientierung und Übersetzung, statt durchgehend zu kommentieren."}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"Wählen Sie Datum und Gruppengröße, um die aktuelle Verfügbarkeit zu prüfen und Ihre Buchung abzuschließen.","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59}},"pickup_dropoff":{"primary":{"name":"Starbucks Hongik University Station Exit 8","address":"Yanghwa-ro, Mapo-gu, Seoul (in front of the Starbucks at Hongik University Station Exit 8)","time":"Abholung 07:30 / Ausstieg 19:00","instructions":"Treffen Sie den Guide an der Starbucks-Filiale unmittelbar oberhalb von Ausgang 8 des Bahnhofs Hongik University. Achten Sie auf das Schild von AtoC Korea und den Bus in der Abholschlange."},"alternates":[{"name":"Myeongdong Station Exit 2 (NorthFace flagship)","address":"Toegye-ro, Jung-gu, Seoul (NorthFace flagship store at Myeongdong Station Exit 2)","time":"Abholung 08:00 / Ausstieg 18:30","instructions":"Treffen Sie den Guide vor dem NorthFace-Flagshipstore oben an Ausgang 2 der Station Myeongdong."}]},"matching_profile":{"profile_version":1,"is_active":true,"product_id":"seoul-gapyeong-nami-morning-calm-petite-france-day-tour","product_type":"bus","route_type":"fixed_route","destination_region":"seoul_gangwon","region_type":"gangwon_seoraksan","vehicle_type":"large_coach","duration_hours":11.5,"region_tags":["seoul_mapo","seoul_jung","gangwon_sokcho","gyeonggi_gapyeong"],"theme_tags":["national_park","mountain","buddhist_temple","k_drama_filming","themed_garden","hallyu_landmark"],"poi_tags":["nami_island","garden_of_morning_calm","petite_france"],"pace_level":0.7,"walking_level":2,"scenic_level":1,"photo_level":5,"culture_level":0.85,"relax_level":0.5,"first_time_fit":1,"family_fit":0.7,"senior_fit":0.8,"couple_fit":1,"solo_traveler_fit":0.9,"active_traveler_fit":0.85,"adult_family_fit":0.95,"family_with_teens_fit":0.95,"young_kids_fit":0.8,"senior_active_fit":0.75,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.6,"one_day_fit":1,"same_day_flight_fit":0.1,"rain_fit":0.5,"value_for_money_fit":1,"iconic_landmark_fit":1,"cafe_fit":0.5,"food_fit":0.5,"nature_fit":1,"beach_fit":0.1,"nightlife_fit":0.1,"shopping_fit":0.25,"no_shopping_fit":1,"local_culture_fit":0.7,"storytelling_fit":0.9,"unesco_fit":0,"intangible_heritage_fit":0.5,"indoor_ratio":0.1,"weather_sensitivity":0.65,"comfort_level":0.55,"budget_fit":1,"premium_fit":0.2,"small_group_fit":0.15,"private_fit":0.05,"bus_fit":1,"price_band":"budget","pickup_base":"seoul_central","return_time_band":"19:00-19:30","duration_band":"13h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited","wheelchair_required"],"notIdealFor":["very_low_mobility","young_kids_under_6"]},"walking_notes":["11.5-hour day with ~4-5 km total walking.","Nami Island is flat; the Garden of Morning Calm is rolling terrain; Petite France sits on a gentle slope.","Closed-toe shoes recommended.","Nami bicycle and e-buggy rental optional and not included."],"keywords":["seoul seoraksan day tour","nami island day trip","garden of morning calm tour","seoul winter wonder tour","seoraksan nami one day"],"synonym_hints":["seoul to seoraksan day tour","korea three signature stops day trip","seoul winter sonata tour"],"seasonality":"year_round","pickup_base_normalized":"seoul","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["nami_island","garden_of_morning_calm","petite_france"],"private_tour_fit":0.05,"customizable_route_fit":0.05,"flexibility_fit":0.2,"fixed_itinerary_fit":1,"national_park_fit":0,"buddhist_temple_fit":0,"k_drama_filming_fit":1,"winter_sonata_fit":1,"themed_garden_fit":1,"history_culture_fit":0.65,"religious_history_fit":0.45,"premium_dining_fit":0.15,"seasonal_fit":1,"winter_lighting_festival_fit":1,"autumn_foliage_fit":1,"china_mainland_market_fit":0.85,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":1,"se_asia_market_fit":1,"us_market_fit":0.95,"europe_market_fit":0.95,"australia_market_fit":0.95,"japan_market_fit":1,"first_time_korea_fit":1,"seoul_day_trip_fit":1,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true},"matching_metadata":{"primary_themes":["gapyeong","seoul_day_trip","k_drama_filming","themed_garden","river_island","french_village"],"secondary_themes":["winter_sonata","metasequoia_lane","lighting_festival","photo_spots","autumn_foliage","first_time_korea"],"best_for":["first_time_korea","couples","photo_lovers","families","k_drama_fans","seniors"],"not_recommended_for":["hikers_seeking_mountains","nightlife_focused_travelers","travelers_wanting_a_short_half_day"],"anchor_pois":["Nami Island","The Garden of Morning Calm","Petite France"],"anchor_poi_keys":["nami_island","garden_of_morning_calm","petite_france"],"competing_products":["seoul-seoraksan-nami-island-morning-calm-day-tour","seoul-private-nami-morning-calm-petite-france","pocheon-sanjeong-lake-herb-island-art-valley"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"No UNESCO property on this route. Cultural weight is popular-culture and horticultural: Winter Sonata''s metasequoia lane on Nami Island, a 330,000 m² private arboretum, and a licensed Le Petit Prince village."},"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","created":"2026-08-04","last_modified":"2026-08-04","version_history":["v1_authored_2026_08_04"],"fix_passes":{"v1_authored_2026_08_04":"New product (owner instruction 2026-08-04). The Gapyeong trio as a join-in-group coach day tour — the join-in counterpart to the existing private seoul-private-nami-morning-calm-petite-france. Donor A (seoul-seoraksan-nami-island-morning-calm-day-tour) supplied the KB-verified Nami Island and Garden of Morning Calm stop bodies plus Seoul-region weather/trust/support blocks and the two-point Seoul pickup; donor B (seoul-private-nami-morning-calm-petite-france) supplied the Petite France stop body. Pickup, lunch, return and all product-level copy authored fresh in 6 locales (scripts/seoul-gapyeong-content/) with de/fr/it/ru staged. Stop admission/hours re-verified 2026-08-04 against operator and KTO sources. matching_profile derived from donor A with the mountain axes zeroed and garden/K-drama axes raised — full KB calibration pending."}},"page_sections":[]}'::jsonb
)
